{
  "rationale": "The caseworker identified that the Pension Credit Guarantee Credit threshold for a single person increased to £238 per week from April 2026. The rule currently uses the 2025-26 rate of £227.10, causing a single claimant with £237.99 weekly income to be incorrectly deemed ineligible. The fix updates the single-person threshold in the derived 'threshold' expression, updates the corresponding clause text (PC-4) to reflect the new figure, and increments the version to 2026-27. The couple threshold is unchanged because the caseworker's evidence only addresses the single rate.",
  "ops": [
    {
      "op": "replace",
      "path": "/derived/2/expr/if/else/const",
      "value": 238.0
    },
    {
      "op": "replace",
      "path": "/clauses/3/text",
      "value": "Guarantee Credit tops up weekly income to £238.00 (single) or £346.60 (couple); eligible if assessed income below threshold."
    },
    {
      "op": "replace",
      "path": "/version",
      "value": "2026-27"
    }
  ],
  "new_version": "2026-27"
}
